using System;
using Comfort.Common;
using EFT;
using EFT.InventoryLogic;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class AiEquipmentRemoval {
 sealed class Request {internal LiveActorReference Actor=null!;internal EquipmentSlot Slot;internal Item Item=null!;internal string Id="",Name="";internal float Started;internal bool Ready,Committed;internal string Error="";internal Callback<IEmptyHandsController>? Callback;}
 static Request? pending;internal static bool Busy=>pending!=null;internal static string Status{get;private set;}="";
 internal static bool Blocks(Player? actor)=>pending is {} request&&actor!=null&&actor.Pointer==request.Actor.Pointer&&actor.ProfileId==request.Actor.Profile;
 internal static void Reset(){pending=null;Status="";}
 static Player Resolve(Request request){var actor=request.Actor.Resolve();if(actor.IsYourPlayer||!actor.IsAI||!AiEquipmentRemovalRules.Allowed(request.Slot.ToString()))throw new ArgumentException("请选择 AI 的头甲或武器槽。");var current=actor.Profile?.Inventory?.Equipment?.GetSlot(request.Slot)?.ContainedItem;if(current==null||!AiEquipmentRemovalRules.Matches(request.Id,request.Item.Pointer.ToInt64(),current.Id,current.Pointer.ToInt64()))throw new ArgumentException("该装备已被更换或移动，未删除新的装备。");return actor;}
 internal static void Start(LiveActorReference actor,EquipmentSlot slot,Item item){if(Busy)throw new ArgumentException("正在处理上一件装备，请稍候。");var request=new Request{Actor=actor,Slot=slot,Item=item,Id=item.Id,Name=LootDisplay.ItemName(item,false),Started=Time.unscaledTime};var target=Resolve(request);pending=request;Status="正在删除 "+actor.Name+" 的 "+request.Name;try{if(target.HandsController?.Item?.Pointer==item.Pointer){target.HandsController.TryCast<Player.FirearmController>()?.SetTriggerPressed(false);target.AIData?.BotOwner?.StopMove();request.Callback=(Action<Result<IEmptyHandsController>>)(result=>{if(!ReferenceEquals(pending,request))return;request.Error=result.Succeed?"":result.Error??"AI 未能收起当前武器。";request.Ready=true;});target.Proceed(false,request.Callback,true);}else request.Ready=true;Tick();}catch{pending=null;throw;}}
 internal static void Tick(){var request=pending;if(request==null)return;try{var target=Resolve(request);if(Time.unscaledTime-request.Started>20)throw new ArgumentException("AI 收起武器超时，装备未删除，请稍后重试。");if(!request.Ready)return;if(request.Error.Length>0)throw new ArgumentException(request.Error);if(target.HandsController?.Item?.Pointer==request.Item.Pointer)return;var controller=target.InventoryController??throw new ArgumentException("AI 库存控制器暂不可用。");var result=ItemManipulator.RemoveWithoutRestrictions(request.Item,controller);if(!result.Succeeded)throw new ArgumentException("游戏未能移除这件装备。");result.Value.RaiseEvents(controller.Cast<IItemOwner>(),CommandStatus.Succeed);var equipment=target.Profile?.Inventory?.Equipment;if(equipment?.GetSlot(request.Slot)?.ContainedItem?.Pointer==request.Item.Pointer||equipment?.TryFindItem(request.Id,out var stillPresent)==true&&stillPresent?.Pointer==request.Item.Pointer)throw new InvalidOperationException("装备移除后仍存在，请刷新检查。");request.Committed=true;pending=null;AiEquipmentEditor.ForgetRemoved(request.Item);WeaponEditor.ForgetRemoved(request.Item);target.RecalculateEquipmentParams();target.Physical?.MarkWeightAsDirty();if(request.Item.TryCast<Weapon>()!=null||request.Slot==EquipmentSlot.Scabbard){var manager=target.AIData?.BotOwner?.WeaponManager;manager?.UpdateWeaponsList();manager?.Selector?.FindItemsInSlots(true);manager?.Selector?.UpdateWeaponsList();if(request.Slot==EquipmentSlot.Scabbard&&manager?.Melee is {} melee){melee.HaveMelee=false;melee.MeleeWeaponEquipped=false;melee.KnifeController=null!;}}Status="已删除："+request.Name+"（含配件）。";FeatureToasts.Show(Status);AiEquipmentEditor.RemovalFinished(request.Actor);}
  catch(Exception e){pending=null;Status=(request.Committed?"装备已删除，刷新提示：":"删除未完成：")+e.Message;FeatureToasts.Show(Status);Plugin.Self.Log.LogWarning("AI equipment removal: "+e.Message);}
 }
}
